<?php
require __DIR__.'/../vendor/autoload.php';$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use Illuminate\Http\Request;
function check($ok,$message){if(!$ok)throw new RuntimeException($message);echo "PASS: $message\n";}
DB::beginTransaction();try{
$tag='checkout-test-'.bin2hex(random_bytes(5));$customer=App\Models\User::create(['name'=>'Checkout fixture','email'=>$tag.'@example.test','password'=>bin2hex(random_bytes(16))]);$admin=App\Models\User::forceCreate(['name'=>'Admin fixture','email'=>$tag.'-admin@example.test','password'=>bin2hex(random_bytes(16)),'is_admin'=>true,'is_super_admin'=>true]);
$product=App\Models\Product::create(['name'=>'Audit product','category_id'=>App\Models\Category::firstOrFail()->id,'regular_price'=>100,'sale_price'=>80,'stock'=>5,'status'=>true,'new_arrival'=>true,'unit'=>'piece']);
$checkout=new App\Http\Controllers\CheckoutController;$orderController=new App\Http\Controllers\OrderController;
function req($data,$user){global $app;$r=Request::create('/checkout','POST',$data);$app->instance('request',$r);$r->setUserResolver(fn()=>$user);$r->setLaravelSession($app->make('session.store'));return $r;}
$data=['customer_name'=>'Checkout fixture','phone'=>'01700000000','email'=>$customer->email,'address'=>'Fixture address','area'=>'inside_dhaka','payment_method'=>'cash_on_delivery','policy_accepted'=>true,'items'=>[['product_id'=>$product->id,'quantity'=>2]],'total'=>1];
$before=App\Models\Order::count();$response=$checkout->store(req($data,$customer));$order=App\Models\Order::latest('id')->first();
check($response->getStatusCode()===303,'Successful checkout uses a client-navigation redirect');check(App\Models\Order::count()===$before+1 && $order->customer_id===$customer->id,'Checkout creates exactly one order linked to customer');check((float)$order->subtotal===160.0 && (float)$order->total===160+(float)$order->delivery_fee,'Checkout calculates server prices and ignores manipulated total');check($product->fresh()->stock===3 && $order->items()->count()===1,'Stock reserves exactly the ordered quantity');
$success=$checkout->success($order,req([],$customer));$successProps=(new ReflectionProperty($success,'props'))->getValue($success);check($successProps['clearCart']===true,'Fresh checkout confirmation clears the cart');$again=$checkout->success($order,req([],$customer));check((new ReflectionProperty($again,'props'))->getValue($again)['clearCart']===false,'Viewing an old confirmation does not clear a new cart');
$orderController->update(req(['status'=>'cancelled','payment_status'=>'unpaid'],$admin),$order);check($product->fresh()->stock===5 && !$order->fresh()->stock_reserved,'Cancelling restores stock');$orderController->update(req(['status'=>'cancelled','payment_status'=>'unpaid'],$admin),$order);check($product->fresh()->stock===5,'Repeated cancellation does not restore stock twice');$orderController->update(req(['status'=>'processing','payment_status'=>'unpaid'],$admin),$order);check($product->fresh()->stock===3,'Reopening reserves stock once');
foreach(['oversell','duplicate','inactive','missing_variant','wrong_variant'] as $case){$bad=$data;if($case==='oversell')$bad['items'][0]['quantity']=100;if($case==='duplicate')$bad['items'][]=$bad['items'][0];if($case==='inactive')$product->update(['status'=>false]);if($case==='missing_variant')$variant=$product->variants()->create(['stock'=>2,'price'=>120]);if($case==='wrong_variant'){$other=App\Models\Product::create(['name'=>'Other fixture','regular_price'=>100,'stock'=>1,'status'=>true]);$otherVariant=$other->variants()->create(['stock'=>1,'price'=>100]);$bad['items'][0]['variant_id']=$otherVariant->id;}
$count=App\Models\Order::count();$stock=$product->fresh()->stock;try{$checkout->store(req($bad,$customer));throw new RuntimeException('Invalid checkout accepted: '.$case);}catch(Illuminate\Validation\ValidationException $e){check(App\Models\Order::count()===$count && $product->fresh()->stock===$stock,$case.' rejected without partial order or stock change');}$product->update(['status'=>true]);}
$customerController=new App\Http\Controllers\CustomerAccountController;$detail=$customerController->showOrder(req([],$customer),$order->id);$props=(new ReflectionProperty($detail,'props'))->getValue($detail);check($props['order']->id===$order->id,'Customer can view their own order');$stranger=App\Models\User::create(['name'=>'Other customer','email'=>$tag.'-other@example.test','password'=>bin2hex(random_bytes(16))]);try{$customerController->showOrder(req([],$stranger),$order->id);throw new RuntimeException('Other order exposed');}catch(Illuminate\Database\Eloquent\ModelNotFoundException $e){echo "PASS: Another customer cannot view this order\n";}
$pdf=(new App\Http\Controllers\CheckoutController)->invoice($order);check(str_starts_with($pdf->getContent(),'%PDF'),'Invoice generates a valid PDF');
}finally{DB::rollBack();}
